import numpy as np

def feature(actions, forecast, state, local, hazards, goal_x, tick):
    """Signed horizontal displacement of the forecast divided by 0.8, clipped to [-1, 1], with dying candidates set to -1."""
    dx = np.clip((forecast[:, 0] - state[0]) / 0.8, -1.0, 1.0)
    alive = forecast[:, 5] > 0.5
    return np.where(alive, dx, -1.0)

import numpy as np

def feature(actions, forecast, state, local, hazards, goal_x, tick):
    """-1 for surviving dash candidates (actions 6/7) when deaths>0 and x <= furthest-4, else 0."""
    x0 = state[0]
    deaths = state[6]
    furthest = state[8]
    in_corridor = (deaths > 0) and (x0 <= furthest - 4)
    if not in_corridor:
        return np.zeros(actions.shape[0])
    is_dash = (actions == 6) | (actions == 7)
    alive = forecast[:, 5] == 1
    return -1.0 * (is_dash & alive).astype(float)
